/**
 * Çıkış lokasyonu ve fasoncu ile taslak sevkiyat açar; numara sunucuda üretilir. Lokasyon kullanıcının
 * yetkili olduğu lokasyonlardan biri olmalıdır. Şoför ve araç henüz belli değilse hiç gönderilmez; şoför
 * kimliği ile adı, araç kimliği ile plakası birlikte gönderilir. Aynı `Idempotency-Key` ile tekrar gönderilen
 * istek yeni sevkiyat açmaz, ilk yanıtı döner.
 * @summary Sevkiyat taslağı oluşturur (DRAFT)
 */
export const createShipment = (
    createShipmentRequest: CreateShipmentRequest,
 ) => {
      return customInstance<CreateShipmentResponse>(
      {url: `/api/v1/shipments`, method: 'POST',
      headers: {'Content-Type': 'application/json', },
      data: createShipmentRequest
    },
      );
    }

/**
 * Fasoncu yalnızca kendi, şoför yalnızca kendisine atanmış, iç kullanıcılar yalnızca yetkili oldukları lokasyonlardaki sevkiyatları görür. Filtre sorguya eklenir (SEC-03).
 * @summary Kapsamdaki sevkiyatlar, en yeni önce
 */
export const listShipments = (
    params?: ListShipmentsParams,
 ) => {
      return customInstance<ShipmentPageResponse>(
      {url: `/api/v1/shipments`, method: 'GET',
        params
    },
      );
    }

/**
 * @summary Sevkiyat ayrıntısı, isteyenin görünümüyle
 */
export const getShipment = (
    shipmentId: string,
 ) => {
      return customInstance<ShipmentDetailResponse>(
      {url: `/api/v1/shipments/${shipmentId}`, method: 'GET'
    },
      );
    }

/**
 * Gövde yoktur; şoför çıkışta kaydedilen çuval sayısını ve mühür numarasını onaylar. Yalnızca sevkiyata
 * atanmış şoför çağırabilir (`allowedActions` içinde `CONFIRM_PICKUP`). Aynı sevkiyat için tekrar gönderilen
 * istek (zayıf bağlantıda yeniden deneme) yeni kayıt oluşturmaz ve yine 204 döner.
 * @summary Şoför yükü teslim aldığını beyan eder (LOADED → IN_TRANSIT)
 */
export const confirmPickup = (
    shipmentId: string,
 ) => {
      return customInstance<void>(
      {url: `/api/v1/shipments/${shipmentId}/pickup-confirmation`, method: 'POST'
    },
      );
    }

